/**
 * Build the `.hornscribe.json` project document (schema v1, FND-001)
 * for the プロジェクトを保存 command (#100).
 *
 * The worker's `project.save` validates this through
 * HornScribeProject.from_dict before writing, so every id here must
 * already satisfy the domain regexes (prj-/rev-/tr-/sn-). Fields the
 * schema does not know (scoreDocument, musicXmlConcert, musicXmlHornF,
 * reviewIssues) ride along as extra keys — preserved verbatim, ignored
 * by the v1 validator, and the data a future project-open restore
 * needs to reconstruct the score without re-transcribing.
 */
import type { LoadedAudio } from "./types";
import type { ScoreDocumentPort } from "../score/document";

/** Fields the app knows at save time. */
export interface ProjectSaveInput {
  readonly audio: LoadedAudio | null;
  readonly doc: ScoreDocumentPort;
  /** Completed job result payload (meta/reviewIssues/scoreDocument). */
  readonly result: unknown;
}

/** `prj-<16hex>` — deterministic content-derived id (ids.py contract). */
export async function deriveProjectId(seed: unknown): Promise<string> {
  // Callers pass a flat object built in fixed key order — plain
  // stringify is deterministic here (same policy as ids.py's canonical
  // JSON digest, minus key sorting which a flat fixed-order object
  // does not need).
  const blob = JSON.stringify(seed);
  const digest = await crypto.subtle.digest(
    "SHA-256",
    new TextEncoder().encode(blob),
  );
  const hex = [...new Uint8Array(digest)]
    .map((b) => b.toString(16).padStart(2, "0"))
    .join("");
  return `prj-${hex.slice(0, 16)}`;
}

function resultMeta(result: unknown): Record<string, unknown> {
  if (typeof result !== "object" || result === null) return {};
  const meta = (result as Record<string, unknown>).meta;
  return typeof meta === "object" && meta !== null
    ? (meta as Record<string, unknown>)
    : {};
}

/** Source ref for the audio backing this score (path-backed only —
 *  browser-dev File refs have no durable path to record). */
function sourceAudioOf(audio: LoadedAudio | null): {
  originalPath: string;
  contentHash: string;
} | null {
  if (!audio) return null;
  const ref = audio.ref;
  if (ref.kind === "path") {
    return { originalPath: ref.path, contentHash: "" };
  }
  if (ref.kind === "recording" && ref.path) {
    return {
      originalPath: ref.path,
      contentHash: ref.contentHash ?? "",
    };
  }
  return null;
}

const REVISION_RE = /^rev-[0-9a-f]{16}$/;
const TRANSCRIPTION_RE = /^tr-[0-9a-f]{16}$/;
const SCORE_NOTE_RE = /^sn-\d{6}$/;

/** True when the document's ids satisfy the v1 schema — a fixture/dev
 *  document (rev-fixture*) cannot be saved and the command should say
 *  so honestly instead of shipping an invalid file. */
export function isSaveableRevision(revisionId: string): boolean {
  return REVISION_RE.test(revisionId);
}

/**
 * Assemble the schema-v1 document. Returns null when the score cannot
 * be represented (non-schema revision id — e.g. the dev fixture doc).
 */
export async function buildProjectDocument(
  input: ProjectSaveInput,
): Promise<Record<string, unknown> | null> {
  const { audio, doc, result } = input;
  if (!isSaveableRevision(doc.revisionId)) return null;
  const meta = resultMeta(result);
  const sourceAudio = sourceAudioOf(audio);

  const transcriptionRevision = meta.transcriptionRevision;
  const transcription =
    typeof transcriptionRevision === "string" &&
    TRANSCRIPTION_RE.test(transcriptionRevision)
      ? {
          backend: String(meta.backend ?? "unknown"),
          backendVersion: String(meta.backendVersion ?? "unknown"),
          settings:
            typeof meta.settings === "object" && meta.settings !== null
              ? meta.settings
              : {},
          revision: transcriptionRevision,
          rawResultRef: `raw/${transcriptionRevision}.json`,
        }
      : null;

  // Canonical-note edits → schema UserEdit records. pitchDelta and
  // deleted are independent facets, so one UI edit can emit two rows.
  const userEdits: Record<string, unknown>[] = [];
  let editSeq = 0;
  for (const [noteId, edit] of doc.noteEdits()) {
    if (!SCORE_NOTE_RE.test(noteId)) continue;
    if (edit.pitchDelta !== 0) {
      userEdits.push({
        id: `ue-${String(++editSeq).padStart(4, "0")}`,
        scoreRevision: doc.revisionId,
        kind: "pitch_change",
        targetNoteIds: [noteId],
        payload: { semitones: edit.pitchDelta },
      });
    }
    if (edit.deleted) {
      userEdits.push({
        id: `ue-${String(++editSeq).padStart(4, "0")}`,
        scoreRevision: doc.revisionId,
        kind: "delete",
        targetNoteIds: [noteId],
        payload: {},
      });
    }
  }

  const reviewDecisions = doc
    .reviewIssues()
    .filter((i) => i.status !== "open")
    .map((i) => ({
      issueId: i.id,
      scoreRevision: doc.revisionId,
      status: i.status,
      note: null,
    }));

  const projectId = await deriveProjectId({
    audioPath: sourceAudio?.originalPath ?? null,
    scoreRevision: doc.revisionId,
    transcriptionRevision: transcriptionRevision ?? null,
  });

  const resultObj =
    typeof result === "object" && result !== null
      ? (result as Record<string, unknown>)
      : {};

  return {
    schemaVersion: 1,
    projectId,
    sourceAudio,
    transcription,
    score: {
      revision: doc.revisionId,
      // The score body travels inline (below); this ref names the
      // canonical cache location a future store would write it to.
      scoreRef: `scores/${doc.revisionId}.json`,
      quantizationSettings:
        typeof meta.settings === "object" && meta.settings !== null
          ? meta.settings
          : {},
    },
    userEdits,
    reviewDecisions,
    uiSession: null,
    // --- preserved extras (ignored by the v1 validator) ---
    scoreDocument: resultObj.scoreDocument ?? null,
    reviewIssues: doc.reviewIssues(),
    musicXmlConcert: doc.musicXml("concert"),
    musicXmlHornF: doc.musicXml("hornF"),
    meta,
  };
}

/**
 * SidecarClient — typed NDJSON protocol client over a {@link SidecarPort}.
 *
 * Implements the shell half of protocol/PROTOCOL.md:
 *
 * - `engine.handshake` on {@link start} (first message after spawn);
 *   a protocol-version mismatch fails explicitly — the worker exits and
 *   the client surfaces the refusal.
 * - request/response correlation by id; events (`job.event`) are demuxed
 *   to subscribers and never disturb pending requests.
 * - per-request timeouts → `SidecarError(REQUEST_TIMEOUT)`.
 * - an in-flight-job watchdog: while any job is active, silence longer
 *   than `watchdogMs` triggers an `engine.ping` probe; a probe timeout
 *   marks the client `unresponsive` (worker.py `debug.hang` proved this
 *   supervision path engine-side).
 * - crash detection: a port exit that was not a requested shutdown marks
 *   the client `crashed`, rejects pending requests with WORKER_CRASHED and
 *   notifies subscribers — the session layer then marks the in-flight job
 *   failed (ADR-0002: never silently resubmitted).
 *
 * Malformed inbound lines are routed to the diagnostics channel and
 * dropped — never answered — mirroring the worker's own containment rule.
 */

import {
  ERR,
  PROTOCOL_VERSION,
  SidecarError,
  encodeFrame,
  isTerminalPhase,
  parseInboundFrame,
  requestFrame,
  type EngineCapabilities,
  type EngineInfo,
  type HandshakeResult,
  type JobCancelResult,
  type JobEventPayload,
  type JobStartResult,
  type PingResult,
  type ProtocolErrorObject,
  type ShutdownResult,
} from "./protocol";
import type { SidecarPort } from "./port";

export type SidecarClientState =
  /** Constructed, not yet started. */
  | "idle"
  /** port.start + handshake in flight. */
  | "starting"
  /** Handshake done — requests may be issued. */
  | "ready"
  /** Graceful shutdown completed (or exit after close). */
  | "closed"
  /** Worker exited without a requested shutdown. */
  | "crashed"
  /** Watchdog probe timed out while a job was in flight. */
  | "unresponsive";

export interface SidecarClientOptions {
  /** Default per-request timeout. */
  requestTimeoutMs?: number;
  /** Handshake timeout — interpreter cold start can be slow (UI-002
   *  measured ≈200 ms locally; packaged first-run may be far slower). */
  handshakeTimeoutMs?: number;
  /** Silence tolerated while a job is in flight before probing. */
  watchdogMs?: number;
  /** Probe (`engine.ping`) timeout once the watchdog fires. */
  pingTimeoutMs?: number;
}

interface PendingRequest {
  method: string;
  resolve: (payload: unknown) => void;
  reject: (err: SidecarError) => void;
  timer: ReturnType<typeof setTimeout>;
}

const DEFAULTS: Required<SidecarClientOptions> = {
  requestTimeoutMs: 10_000,
  handshakeTimeoutMs: 30_000,
  watchdogMs: 15_000,
  pingTimeoutMs: 5_000,
};

export class SidecarClient {
  private readonly port: SidecarPort;
  private readonly opts: Required<SidecarClientOptions>;
  private state: SidecarClientState = "idle";
  private counter = 0;
  private readonly pending = new Map<string, PendingRequest>();
  private readonly jobEventCbs = new Set<(e: JobEventPayload) => void>();
  private readonly stateCbs = new Set<(s: SidecarClientState) => void>();
  private readonly diagCbs = new Set<(line: string) => void>();
  private readonly activeJobs = new Set<string>();
  private watchdogTimer: ReturnType<typeof setTimeout> | null = null;
  private probing = false;
  private shutdownRequested = false;
  private handshakeResult: HandshakeResult | null = null;

  constructor(port: SidecarPort, opts: SidecarClientOptions = {}) {
    this.port = port;
    this.opts = { ...DEFAULTS, ...opts };
    port.onLine((line) => this.handleLine(line));
    port.onStderr((line) => this.diagnose(`stderr: ${line}`));
    port.onExit((code) => this.handleExit(code));
  }

  // ---- surface ---------------------------------------------------------

  getState(): SidecarClientState {
    return this.state;
  }

  get engineInfo(): EngineInfo | null {
    return this.handshakeResult?.engineInfo ?? null;
  }

  get capabilities(): EngineCapabilities | null {
    return this.handshakeResult?.capabilities ?? null;
  }

  get handshake(): HandshakeResult | null {
    return this.handshakeResult;
  }

  /** Ids of jobs started via this client that have not reached a
   *  terminal event (used by the session for crash bookkeeping). */
  get inFlightJobs(): readonly string[] {
    return [...this.activeJobs];
  }

  onJobEvent(cb: (e: JobEventPayload) => void): () => void {
    this.jobEventCbs.add(cb);
    return () => this.jobEventCbs.delete(cb);
  }

  onStateChange(cb: (s: SidecarClientState) => void): () => void {
    this.stateCbs.add(cb);
    return () => this.stateCbs.delete(cb);
  }

  /** Diagnostics channel: malformed inbound frames, stderr lines,
   *  supervision notes. Never user-facing copy. */
  onDiagnostic(cb: (line: string) => void): () => void {
    this.diagCbs.add(cb);
    return () => this.diagCbs.delete(cb);
  }

  private setState(s: SidecarClientState): void {
    if (this.state === s) return;
    this.state = s;
    for (const cb of [...this.stateCbs]) cb(s);
  }

  private diagnose(line: string): void {
    for (const cb of [...this.diagCbs]) cb(line);
  }

  // ---- lifecycle ---------------------------------------------------------

  /**
   * Spawn the worker and run `engine.handshake`. Resolves with the
   * handshake result once the engine is `ready`. Rejects on spawn failure,
   * timeout, or a PROTOCOL_VERSION_MISMATCH refusal (the worker then exits
   * and `crashed` is signalled via the exit path).
   */
  async start(): Promise<HandshakeResult> {
    if (this.state !== "idle") {
      throw new SidecarError(
        ERR.ENGINE_NOT_READY,
        `client.start() from state '${this.state}'`,
      );
    }
    this.setState("starting");
    try {
      await this.port.start();
    } catch (e) {
      this.setState("crashed");
      throw e instanceof SidecarError
        ? e
        : new SidecarError(ERR.ENGINE_UNAVAILABLE, String(e));
    }
    let result: HandshakeResult;
    try {
      result = (await this.requestRaw(
        "engine.handshake",
        {
          protocolVersion: PROTOCOL_VERSION,
          clientInfo: { name: "hornscribe-desktop", surface: "react" },
        },
        this.opts.handshakeTimeoutMs,
        /* allowBeforeReady */ true,
      )) as HandshakeResult;
    } catch (e) {
      // Timeout / refusal / dead port — never leave the client wedged in
      // "starting"; the exit event may also mark it crashed, both are dead.
      if (this.getState() === "starting") this.setState("crashed");
      throw e;
    }
    if (result.protocolVersion !== PROTOCOL_VERSION) {
      this.setState("crashed");
      throw new SidecarError(
        ERR.PROTOCOL_VERSION_MISMATCH,
        `worker reported protocolVersion ${String(result.protocolVersion)}`,
      );
    }
    this.handshakeResult = result;
    this.setState("ready");
    return result;
  }

  /** Graceful shutdown: `engine.shutdown`, then stdin EOF fallback, and
   *  finally a bounded wait for the exit event. Never throws. */
  async shutdown(timeoutMs = 3_000): Promise<void> {
    if (this.state === "closed" || this.state === "crashed") {
      this.setState("closed");
      return;
    }
    this.shutdownRequested = true;
    try {
      if (this.state === "ready") {
        await this.requestRaw<ShutdownResult>(
          "engine.shutdown",
          {},
          Math.min(timeoutMs, this.opts.requestTimeoutMs),
          true,
        );
      }
    } catch {
      // The worker may already be gone — stdin EOF below is the fallback.
    }
    try {
      this.port.closeStdin();
    } catch {
      /* port already dead */
    }
    // Bounded wait for the exit event; then mark closed regardless —
    // shutdown must not hang the UI.
    const deadline = Date.now() + timeoutMs;
    while (
      this.getState() !== "closed" &&
      this.getState() !== "crashed" &&
      Date.now() < deadline
    ) {
      await new Promise((r) => setTimeout(r, 15));
    }
    this.clearWatchdog();
    this.rejectAllPending(new SidecarError(ERR.ENGINE_NOT_READY, "client shut down"));
    this.setState("closed");
  }

  /** Liveness + latency probe. */
  async ping(echo: unknown = null): Promise<PingResult> {
    return this.request<PingResult>("engine.ping", { echo });
  }

  /** `job.start` — returns {jobId, jobKind, state:"accepted"}.
   *  JOB_ALREADY_RUNNING is enforced engine-side. */
  async startJob(jobKind: string, params: unknown): Promise<JobStartResult> {
    const res = await this.request<JobStartResult>("job.start", {
      jobKind,
      params,
    });
    this.activeJobs.add(res.jobId);
    this.armWatchdog();
    return res;
  }

  /** `job.cancel` — cooperative: the job emits its terminal `cancelled`
   *  event at the next checkpoint. JOB_NOT_FOUND means it already ended. */
  async cancelJob(jobId: string): Promise<JobCancelResult> {
    return this.request<JobCancelResult>("job.cancel", { jobId });
  }

  /** Generic engine method call (#100: `project.save` and future
   *  non-job methods). Same correlation/timeout discipline as the
   *  job verbs; requires the client to be `ready`. */
  async call<T>(method: string, payload: unknown): Promise<T> {
    return this.request<T>(method, payload);
  }

  // ---- requests -----------------------------------------------------------

  private async request<T>(method: string, payload: unknown): Promise<T> {
    return this.requestRaw<T>(method, payload, this.opts.requestTimeoutMs, false);
  }

  private requestRaw<T>(
    method: string,
    payload: unknown,
    timeoutMs: number,
    allowBeforeReady: boolean,
  ): Promise<T> {
    if (!allowBeforeReady && this.state !== "ready") {
      return Promise.reject(
        new SidecarError(
          ERR.ENGINE_NOT_READY,
          `cannot issue '${method}' while client is '${this.state}'`,
        ),
      );
    }
    this.counter += 1;
    const id = `req-${String(this.counter).padStart(6, "0")}`;
    return new Promise<T>((resolve, reject) => {
      const timer = setTimeout(() => {
        this.pending.delete(id);
        reject(
          new SidecarError(
            ERR.REQUEST_TIMEOUT,
            `no response to '${method}' within ${timeoutMs}ms`,
            { method, id },
          ),
        );
      }, timeoutMs);
      this.pending.set(id, {
        method,
        resolve: resolve as (p: unknown) => void,
        reject,
        timer,
      });
      try {
        this.port.writeLine(encodeFrame(requestFrame(id, method, payload)));
      } catch (e) {
        clearTimeout(timer);
        this.pending.delete(id);
        reject(
          e instanceof SidecarError
            ? e
            : new SidecarError(ERR.ENGINE_UNAVAILABLE, String(e)),
        );
      }
    });
  }

  // ---- inbound frames -------------------------------------------------------

  private handleLine(line: string): void {
    this.touch();
    const frame = parseInboundFrame(line);
    if (!frame) {
      this.diagnose(`dropped malformed inbound frame: ${line.slice(0, 200)}`);
      return;
    }
    if (frame.kind === "response") {
      this.handleResponse(frame.id, frame.method, frame.payload, frame.error);
    } else {
      this.handleEvent(frame.method, frame.payload);
    }
  }

  private handleResponse(
    id: string | null,
    method: string | null,
    payload: unknown,
    error: ProtocolErrorObject | null,
  ): void {
    if (id === null) {
      // The one sanctioned null-id response: the worker could not recover
      // an id from a frame it rejected. We never send unrecoverable
      // frames, so this is a diagnostics curiosity, not a request result.
      this.diagnose(
        `null-id error response (${method ?? "?"}): ${error?.code ?? "?"} ${error?.message ?? ""}`,
      );
      return;
    }
    const pending = this.pending.get(id);
    if (!pending) {
      this.diagnose(`response for unknown id '${id}' dropped`);
      return;
    }
    clearTimeout(pending.timer);
    this.pending.delete(id);
    if (error) {
      pending.reject(new SidecarError(error.code, error.message, error.details));
    } else {
      pending.resolve(payload);
    }
  }

  private handleEvent(method: string | null, payload: unknown): void {
    if (method !== "job.event") {
      this.diagnose(`event '${method ?? "?"}' dropped (no subscriber)`);
      return;
    }
    const body = (payload ?? {}) as JobEventPayload;
    if (typeof body.jobId !== "string" || typeof body.phase !== "string") {
      this.diagnose("job.event without jobId/phase dropped");
      return;
    }
    if (isTerminalPhase(body.phase)) {
      this.activeJobs.delete(body.jobId);
      if (this.activeJobs.size === 0) this.clearWatchdog();
    }
    for (const cb of [...this.jobEventCbs]) cb(body);
  }

  // ---- crash / watchdog ------------------------------------------------------

  private touch(): void {
    if (this.activeJobs.size > 0 && this.state === "ready") this.armWatchdog();
  }

  private armWatchdog(): void {
    this.clearWatchdog();
    if (this.state !== "ready" || this.activeJobs.size === 0) return;
    this.watchdogTimer = setTimeout(() => void this.probe(), this.opts.watchdogMs);
  }

  private clearWatchdog(): void {
    if (this.watchdogTimer !== null) {
      clearTimeout(this.watchdogTimer);
      this.watchdogTimer = null;
    }
  }

  /** Watchdog probe: the job produced no frames for watchdogMs — ping the
   *  worker; if even that times out, declare it unresponsive. */
  private async probe(): Promise<void> {
    if (this.probing || this.state !== "ready" || this.activeJobs.size === 0) {
      return;
    }
    this.probing = true;
    try {
      await this.requestRaw(
        "engine.ping",
        { echo: "watchdog" },
        this.opts.pingTimeoutMs,
        true,
      );
      // Alive — re-arm. A busy worker answers ping even mid-job (the
      // dispatch loop is independent of the job thread).
      this.armWatchdog();
    } catch {
      this.setState("unresponsive");
      this.clearWatchdog();
      this.diagnose("worker did not answer watchdog ping — unresponsive");
      this.rejectAllPending(
        new SidecarError(ERR.WORKER_UNRESPONSIVE, "worker is not responding"),
      );
    } finally {
      this.probing = false;
    }
  }

  private handleExit(code: number | null): void {
    this.clearWatchdog();
    const graceful = this.shutdownRequested || code === 0;
    this.rejectAllPending(
      new SidecarError(
        graceful ? ERR.ENGINE_NOT_READY : ERR.WORKER_CRASHED,
        graceful ? "worker shut down" : `worker exited (code ${String(code)})`,
      ),
    );
    this.setState(graceful ? "closed" : "crashed");
    if (!graceful) {
      this.diagnose(`worker exited unexpectedly (code ${String(code)})`);
    }
  }

  private rejectAllPending(err: SidecarError): void {
    for (const [, p] of this.pending) {
      clearTimeout(p.timer);
      p.reject(err);
    }
    this.pending.clear();
  }
}

/**
 * TranscriptionSession — the app-facing engine/job state machine
 * (GUI_UX_SPEC §5, §27; ADR-0002 failure model).
 *
 * One job at a time (the worker enforces `maxConcurrentJobs: 1`).
 * The session owns a {@link SidecarClient} built on a port factory, so a
 * crashed worker can be replaced by a fresh spawn without restarting the
 * UI — restart is an explicit recovery action, never silent resubmission.
 *
 * State is exposed as an immutable {@link SessionSnapshot} via
 * `subscribe()` — React consumes it through a single `useEffect`, and the
 * §27 screen machine maps it to `transcribing` / `transcriptionError` /
 * `scoreReady` / `audioReady`.
 */

import { SidecarClient, type SidecarClientOptions } from "./client";
import {
  ERR,
  SidecarError,
  type EngineCapabilities,
  type EngineInfo,
  type JobEventPayload,
  type JobStartResult,
} from "./protocol";
import type { SidecarPort } from "./port";
import {
  createJobView,
  markCancelling,
  markJobDead,
  reduceJobEvent,
  type JobView,
} from "./jobView";
import { extractReviewIssueCount } from "./review";

/** Real transcription job kind; the spike worker only knows
 *  `demoLongTask`, so the session falls back to it when `transcription`
 *  is not in `capabilities.jobKinds` — documented as the UI-002→UI-040
 *  bridge until the engine ships the real kind. */
export const TRANSCRIPTION_JOB_KIND = "transcription";
export const FALLBACK_JOB_KIND = "demoLongTask";

export type EngineStatus =
  /** No client yet (never started, or torn down). */
  | "offline"
  /** Spawn + handshake in flight. */
  | "starting"
  /** Handshake done — the engine can accept jobs. */
  | "ready"
  /** Worker exited unexpectedly (crash). Restart is an explicit action. */
  | "crashed"
  /** Watchdog: worker stopped answering mid-job. */
  | "unresponsive"
  /** Graceful shutdown completed. */
  | "closed";

/**
 * The failure classes the §20 error surfaces distinguish:
 * - `transcriptionFailed` — the job ended in a terminal `failed` event
 *   while the engine stayed alive → 再試行 is meaningful.
 * - `workerCrashed` — the process died mid-job → エンジンを再起動.
 * - `workerNotResponding` — watchdog probe timed out → エンジンを再起動.
 */
export type FailureKind =
  | "transcriptionFailed"
  | "workerCrashed"
  | "workerNotResponding";

export interface SessionFailure {
  kind: FailureKind;
  /** Machine-readable detail for the diagnostics surface — codes and
   *  engine messages stay OUT of normal UI copy (JAPANESE_UI_COPY §7). */
  detail: string;
  errorCode?: string;
}

export interface SessionSnapshot {
  engine: EngineStatus;
  engineInfo: EngineInfo | null;
  capabilities: EngineCapabilities | null;
  /** In-flight or just-ended job — null when idle. */
  job: JobView | null;
  /** Set on terminal failure; cleared on retry/restart/dismiss. */
  failure: SessionFailure | null;
  /**
   * The `completed` event's `result` payload — the score-data handoff
   * point. UI-030's adapter consumes this to build the canonical score
   * view; UI-040 only guarantees it is preserved verbatim and never
   * mutated by the progress layer.
   */
  lastResult: unknown;
  /** Count of open review issues in `lastResult` (0 when none). */
  reviewIssueCount: number;
  /** Recent supervision diagnostics (stderr + client notes). Ring buffer. */
  diagnostics: readonly string[];
}

type Listener = (snapshot: SessionSnapshot) => void;

export interface TranscriptionSessionOptions {
  portFactory: () => SidecarPort;
  clientOptions?: SidecarClientOptions;
  /** Max retained diagnostic lines. */
  diagnosticLogLimit?: number;
  /** Wall clock — injectable for tests. */
  now?: () => number;
}

const DEFAULT_DIAGNOSTIC_LIMIT = 80;

export class TranscriptionSession {
  private readonly portFactory: () => SidecarPort;
  private readonly clientOptions?: SidecarClientOptions;
  private readonly logLimit: number;
  private readonly now: () => number;
  private client: SidecarClient | null = null;
  private readonly listeners = new Set<Listener>();
  private snap: SessionSnapshot = {
    engine: "offline",
    engineInfo: null,
    capabilities: null,
    job: null,
    failure: null,
    lastResult: null,
    reviewIssueCount: 0,
    diagnostics: [],
  };
  private logLines: string[] = [];

  constructor(opts: TranscriptionSessionOptions) {
    this.portFactory = opts.portFactory;
    this.clientOptions = opts.clientOptions;
    this.logLimit = opts.diagnosticLogLimit ?? DEFAULT_DIAGNOSTIC_LIMIT;
    this.now = opts.now ?? (() => Date.now());
  }

  // ---- subscription -------------------------------------------------------

  getSnapshot(): SessionSnapshot {
    return this.snap;
  }

  subscribe(cb: Listener): () => void {
    this.listeners.add(cb);
    return () => this.listeners.delete(cb);
  }

  private update(patch: Partial<SessionSnapshot>): void {
    this.snap = { ...this.snap, ...patch };
    for (const cb of [...this.listeners]) cb(this.snap);
  }

  private log(line: string): void {
    this.logLines = [...this.logLines.slice(-(this.logLimit - 1)), line];
    this.update({ diagnostics: this.logLines });
  }

  // ---- engine lifecycle ------------------------------------------------------

  private buildClient(): SidecarClient {
    const client = new SidecarClient(this.portFactory(), this.clientOptions);
    client.onJobEvent((e) => this.onJobEvent(e));
    client.onStateChange((s) => this.onClientState(s));
    client.onDiagnostic((l) => this.log(l));
    return client;
  }

  /** Lazily spawn + handshake. Idempotent while `ready`. */
  private async ensureEngine(): Promise<void> {
    if (this.client && this.snap.engine === "ready") return;
    this.update({ engine: "starting" });
    const client = this.buildClient();
    this.client = client;
    try {
      const hs = await client.start();
      this.update({
        engine: "ready",
        engineInfo: hs.engineInfo,
        capabilities: hs.capabilities,
      });
    } catch (e) {
      // Spawn/handshake failure → the engine is down, the error surface
      // offers エンジンを再起動 (which builds a fresh port+client).
      this.update({
        engine: "crashed",
        failure: {
          kind: "workerNotResponding",
          detail: e instanceof Error ? e.message : String(e),
          errorCode: e instanceof SidecarError ? e.code : undefined,
        },
      });
      throw e;
    }
  }

  /**
   * エンジンを再起動 — the crash/unresponsive recovery action (§20).
   * Tears down the old client (best-effort shutdown, then kill) and runs
   * a fresh spawn + handshake. Never resubmits a job.
   */
  async restartEngine(): Promise<void> {
    const old = this.client;
    this.client = null;
    if (old) {
      old.shutdown(800).catch(() => undefined);
    }
    this.update({ engine: "starting", failure: null });
    const client = this.buildClient();
    this.client = client;
    try {
      const hs = await client.start();
      this.update({
        engine: "ready",
        engineInfo: hs.engineInfo,
        capabilities: hs.capabilities,
      });
    } catch (e) {
      this.update({
        engine: "crashed",
        failure: {
          kind: "workerNotResponding",
          detail: e instanceof Error ? e.message : String(e),
          errorCode: e instanceof SidecarError ? e.code : undefined,
        },
      });
      throw e;
    }
  }

  /** Graceful teardown for app shutdown — never throws. */
  async dispose(): Promise<void> {
    const client = this.client;
    this.client = null;
    if (client) await client.shutdown();
    this.update({ engine: "closed" });
  }

  /**
   * `project.save` (#100): persist a .hornscribe.json document through
   * the engine. Spawns the engine lazily when it is not already up —
   * the same engine that produced the score normally still serves.
   */
  async saveProject(path: string, project: unknown): Promise<{ path: string; projectId: string }> {
    await this.ensureEngine();
    const client = this.client;
    if (!client) {
      throw new SidecarError(ERR.ENGINE_UNAVAILABLE, "no engine client");
    }
    return client.call<{ path: string; projectId: string }>(
      "project.save",
      { path, project },
    );
  }

  // ---- jobs --------------------------------------------------------------------

  /** The jobKind to request: `transcription` when the engine advertises
   *  it, else the spike stand-in (documented bridge). */
  private transcriptionJobKind(): string {
    const kinds = this.snap.capabilities?.jobKinds;
    if (Array.isArray(kinds) && kinds.includes(TRANSCRIPTION_JOB_KIND)) {
      return TRANSCRIPTION_JOB_KIND;
    }
    return FALLBACK_JOB_KIND;
  }

  /**
   * `score.transcribe` → `job.start`. Explicit user action only — retry is
   * never silent (issue rule). Resolves once the job is accepted; progress
   * arrives as job.event frames afterwards.
   */
  async startTranscription(params: unknown = {}): Promise<void> {
    if (this.snap.job && !isSettled(this.snap.job)) {
      throw new SidecarError(ERR.JOB_ALREADY_RUNNING, "a job is already running");
    }
    this.update({ failure: null, lastResult: null, reviewIssueCount: 0 });
    await this.ensureEngine();
    const client = this.client;
    if (!client) {
      throw new SidecarError(ERR.ENGINE_UNAVAILABLE, "no engine client");
    }
    const kind = this.transcriptionJobKind();
    let accepted: JobStartResult;
    try {
      accepted = await client.startJob(kind, params);
    } catch (e) {
      // job.start itself was rejected (request timeout, INVALID_PARAMS, a
      // racing JOB_ALREADY_RUNNING). Surface an honest failure rather than
      // leaving the screen on a job that never existed — unless crash
      // supervision already set a stronger one (don't downgrade it).
      if (!this.snap.failure) {
        this.update({
          failure: {
            kind: "transcriptionFailed",
            detail: e instanceof Error ? e.message : String(e),
            errorCode: e instanceof SidecarError ? e.code : undefined,
          },
        });
      }
      throw e;
    }
    this.update({
      job: createJobView(accepted.jobId, kind, this.now()),
    });
  }

  /**
   * `job.cancel` — cooperative (PROTOCOL.md): the job ends in a terminal
   * `cancelled` event at the next checkpoint, so this resolves while the
   * job is still finishing. The UI shows the honest `cancelling` state
   * until the terminal event arrives.
   */
  async cancelTranscription(): Promise<void> {
    const job = this.snap.job;
    const client = this.client;
    if (!job || isSettled(job) || !client) return;
    if (job.phase === "cancelling") return;
    this.update({ job: markCancelling(job) });
    try {
      await client.cancelJob(job.jobId);
    } catch (e) {
      if (e instanceof SidecarError && e.code === ERR.JOB_NOT_FOUND) {
        // The job already reached a terminal event — fine, it wins.
        return;
      }
      // The cancel request itself failed — restore the honest running
      // state so the button does not lie about a pending cancel. Fold the
      // flag back onto the CURRENT view so progress/stage events that
      // arrived in the meantime are not lost.
      const current = this.snap.job;
      if (
        current &&
        current.jobId === job.jobId &&
        current.phase === "cancelling"
      ) {
        this.update({ job: { ...current, phase: "running" } });
      }
      throw e;
    }
  }

  // ---- event/state handling ----------------------------------------------------

  private onJobEvent(event: JobEventPayload): void {
    const job = this.snap.job;
    if (!job || event.jobId !== job.jobId) return;
    const next = reduceJobEvent(job, event);
    const patch: Partial<SessionSnapshot> = { job: next };
    if (next.phase === "completed") {
      patch.lastResult = next.result;
      patch.reviewIssueCount = extractReviewIssueCount(next.result);
    } else if (next.phase === "failed" && next.error) {
      // Engine stayed alive, the job failed → 再試行 surface.
      patch.failure = {
        kind: "transcriptionFailed",
        detail: `${next.error.code}: ${next.error.message}`,
        errorCode: next.error.code,
      };
    }
    this.update(patch);
  }

  private onClientState(state: string): void {
    switch (state) {
      case "ready":
        this.update({ engine: "ready" });
        break;
      case "starting":
        this.update({ engine: "starting" });
        break;
      case "closed":
        this.update({ engine: "closed" });
        break;
      case "crashed":
      case "unresponsive": {
        const engine = state as EngineStatus;
        const kind: FailureKind =
          state === "crashed" ? "workerCrashed" : "workerNotResponding";
        const code =
          state === "crashed" ? ERR.WORKER_CRASHED : ERR.WORKER_UNRESPONSIVE;
        const job = this.snap.job;
        const patch: Partial<SessionSnapshot> = { engine };
        // ADR-0002: an in-flight job gets NO terminal event from a dead
        // worker — the supervisor marks it failed explicitly.
        if (job && !isSettled(job)) {
          patch.job = markJobDead(job, {
            code,
            message:
              state === "crashed"
                ? "worker process exited while the job was in flight"
                : "worker did not answer the watchdog probe",
          });
          patch.failure = { kind, detail: code, errorCode: code };
        } else if (this.snap.engine === "ready" || this.snap.engine === "starting") {
          // Idle-engine death is reported through `engine` alone — the
          // status bar shows it; no modal error for a silent worker.
        }
        this.update(patch);
        break;
      }
    }
  }

  // ---- terminal bookkeeping ------------------------------------------------------

  /**
   * Clear the settled job record after the UI has consumed the terminal
   * state (completed → scoreReady handoff, cancelled → audioReady). The
   * `lastResult` handoff payload is preserved.
   */
  clearJob(): void {
    const job = this.snap.job;
    if (job && isSettled(job)) this.update({ job: null });
  }

  /** Dismiss the failure surface — the workspace returns to its prior
   *  valid state (audio stays loaded, a prior score is never destroyed). */
  clearFailure(): void {
    if (this.snap.failure) this.update({ failure: null });
  }

  /** Diagnostics text for the 診断情報 dialog (GUI_UX_SPEC §19 fields the
   *  session can honestly report; tool checks belong to UI-060). */
  buildDiagnostics(): string {
    const s = this.snap;
    const lines: string[] = [
      "HornScribe desktop — transcription session",
      `protocolVersion: 1`,
      `engine: ${s.engine}`,
      `engineInfo: ${s.engineInfo ? JSON.stringify(s.engineInfo) : "(none)"}`,
      `jobKinds: ${JSON.stringify(s.capabilities?.jobKinds ?? [])}`,
      `cooperativeCancel: ${String(s.capabilities?.cooperativeCancel ?? "?")}`,
      `cancellationFallback: ${String(s.capabilities?.cancellationFallback ?? "?")}`,
      `job: ${s.job ? `${s.job.jobId} ${s.job.phase}` : "(none)"}`,
      `failure: ${s.failure ? `${s.failure.kind} (${s.failure.detail})` : "(none)"}`,
      "— recent engine diagnostics —",
      ...s.diagnostics.slice(-30),
    ];
    return lines.join("\n");
  }
}

function isSettled(job: JobView): boolean {
  return (
    job.phase === "completed" ||
    job.phase === "cancelled" ||
    job.phase === "failed"
  );
}

"""HornScribe engine sidecar worker (UI-002 spike).

Speaks the NDJSON protocol in ``protocol/PROTOCOL.md`` over stdin/stdout:
stdout carries protocol frames only, all diagnostics go to stderr.

Lifecycle contract (ADR-0002):

- requests are dispatched sequentially on the stdin read loop
- jobs run on daemon threads so the loop stays responsive (progress
  events stream while ``engine.ping`` etc. keep answering)
- ``engine.shutdown`` replies, then the worker exits 0
- stdin EOF is an implicit graceful shutdown (also exit 0)
- an incompatible ``engine.handshake`` protocol version is refused with
  ``PROTOCOL_VERSION_MISMATCH`` and the worker exits — it will not serve
  a peer it cannot talk to
- at most one job is in flight (``JOB_ALREADY_RUNNING``); the spike does
  not need a pool before evidence requires it (issue non-goals)
"""

from __future__ import annotations

import argparse
import contextlib
import importlib.util
import logging
import os
import platform
import sys
import threading
import time
from collections.abc import Callable
from dataclasses import dataclass, field
from pathlib import Path
from typing import Any, TextIO

import hornscribe
from hornscribe.project.errors import ProjectError
from hornscribe.project.model import (
    PROJECT_FILE_SUFFIX,
    HornScribeProject,
    hash_file_sha256,
)
from hornscribe.project.store import ProjectStore
from hornscribe.transcription import (
    JOB_KIND_TRANSCRIPTION,
    TranscriptionParams,
    run_transcription_job,
)
from hornscribe.worker import protocol
from hornscribe.worker.jobs import (
    JOB_KIND_DEMO_LONG_TASK,
    DemoLongTaskParams,
    run_demo_long_task,
)

# Job kinds this worker accepts. ``transcription`` (ENG-002) is the real
# pipeline; ``demoLongTask`` stays for protocol/regression tests.
SUPPORTED_JOB_KINDS: tuple[str, ...] = (
    JOB_KIND_TRANSCRIPTION,
    JOB_KIND_DEMO_LONG_TASK,
)

log = logging.getLogger("hornscribe.worker")

_SHUTDOWN_JOIN_TIMEOUT_S = 2.0


@dataclass
class _Job:
    """Handle for one in-flight job thread."""

    job_id: str
    kind: str
    cancel: threading.Event
    done: threading.Event = field(default_factory=threading.Event)
    thread: threading.Thread | None = None


class Worker:
    """The sidecar process: sequential requests, threaded jobs."""

    def __init__(self, stdin: TextIO, stdout: TextIO) -> None:
        self._stdin = stdin
        self._stdout = stdout
        self._write_lock = threading.Lock()
        self._shutdown = threading.Event()
        self._exit_after_response = False
        self._job: _Job | None = None
        self._job_counter = 0
        self._started = time.monotonic()
        self._methods: dict[str, Callable[[Any], dict[str, Any]]] = {
            "engine.handshake": self._handle_handshake,
            "engine.ping": self._handle_ping,
            "engine.shutdown": self._handle_shutdown,
            "job.start": self._handle_job_start,
            "job.cancel": self._handle_job_cancel,
            # #100: persist a .hornscribe.json project document (schema
            # v1) — the save path the UI's プロジェクトを保存 command
            # calls. Validation runs through HornScribeProject.from_dict
            # so a malformed document is rejected, never written.
            "project.save": self._handle_project_save,
            # Spike-only supervisor test hook: wedges the dispatch loop so
            # the supervisor-side read timeout path can be exercised.
            # Not a stable API; gated on the "debug." prefix.
            "debug.hang": self._handle_debug_hang,
            # Stack dump of every thread (diagnostics for a stalled job).
            "debug.stacks": self._handle_debug_stacks,
        }

    # ---- frame IO -----------------------------------------------------

    def _send(self, envelope: protocol.Envelope) -> None:
        line = protocol.encode_message(envelope)
        with self._write_lock:
            self._stdout.write(line + "\n")
            self._stdout.flush()

    def _respond(self, request_id: str, method: str | None, payload: Any) -> None:
        self._send(protocol.make_response(request_id, method, payload))

    def _respond_error(
        self,
        request_id: str | None,
        method: str | None,
        code: str,
        message: str,
        details: dict[str, Any] | None = None,
    ) -> None:
        self._send(
            protocol.make_error_response(
                request_id, code, message, details=details, method=method
            )
        )

    def _emit_event(self, method: str, payload: dict[str, Any]) -> None:
        self._send(protocol.make_event(method, payload))

    # ---- main loop ----------------------------------------------------

    def serve(self) -> int:
        """Run the read/dispatch loop until shutdown or stdin EOF."""
        log.info(
            "sidecar started pid=%d protocol=v%d hornscribe=%s",
            os.getpid(),
            protocol.PROTOCOL_VERSION,
            hornscribe.__version__,
        )
        while not self._shutdown.is_set():
            line = self._stdin.readline()
            if line == "":
                log.info("stdin EOF; shutting down")
                break
            self._handle_line(line)
            if self._exit_after_response:
                break
        self._shutdown_gracefully()
        log.info("sidecar stopped")
        return 0

    def _shutdown_gracefully(self) -> None:
        job = self._job
        if job is not None and not job.done.is_set():
            log.info("cancelling active job %s for shutdown", job.job_id)
            job.cancel.set()
            if job.thread is not None:
                job.thread.join(timeout=_SHUTDOWN_JOIN_TIMEOUT_S)

    def _handle_line(self, line: str) -> None:
        try:
            msg = protocol.parse_message(line)
        except protocol.ProtocolError as exc:
            log.warning("rejected inbound frame: %s", exc)
            self._respond_error(exc.request_id, None, exc.code, exc.message, exc.details)
            return
        if msg.kind != protocol.KIND_REQUEST:
            # The peer only ever sends requests. Inbound responses/events
            # are logged and dropped — never answered — to avoid any
            # chance of a reply loop.
            log.warning("ignoring inbound %s frame id=%s", msg.kind, msg.id)
            return
        assert msg.id is not None
        assert msg.method is not None
        handler = self._methods.get(msg.method)
        if handler is None:
            self._respond_error(
                msg.id,
                msg.method,
                protocol.ERR_UNKNOWN_METHOD,
                f"unknown method {msg.method!r}",
                details={"methods": sorted(self._methods)},
            )
            return
        try:
            payload = handler(msg.payload)
        except protocol.ProtocolError as exc:
            self._respond_error(msg.id, msg.method, exc.code, exc.message, exc.details)
            return
        except Exception:
            # Errors are structured data, never raw tracebacks (ADR-0002);
            # the traceback stays on stderr where diagnostics belong.
            log.exception("handler failed for %s", msg.method)
            self._respond_error(
                msg.id, msg.method, protocol.ERR_INTERNAL, "internal worker error"
            )
            return
        self._respond(msg.id, msg.method, payload)

    # ---- method handlers ----------------------------------------------

    def _handle_handshake(self, payload: Any) -> dict[str, Any]:
        params = payload if isinstance(payload, dict) else {}
        client_v = params.get("protocolVersion", protocol.PROTOCOL_VERSION)
        if client_v != protocol.PROTOCOL_VERSION:
            # Refuse explicitly, then exit: a worker that cannot speak the
            # peer's version must not limp along (ADR-0002).
            self._exit_after_response = True
            raise protocol.ProtocolError(
                protocol.ERR_PROTOCOL_VERSION_MISMATCH,
                f"client requested protocol v{client_v!r}; "
                f"worker speaks v{protocol.PROTOCOL_VERSION}",
                details={
                    "requested": client_v,
                    "supported": [protocol.PROTOCOL_VERSION],
                },
            )
        return {
            "protocolVersion": protocol.PROTOCOL_VERSION,
            "engineInfo": {
                "name": "hornscribe-engine",
                "version": hornscribe.__version__,
                "python": platform.python_version(),
                "platform": sys.platform,
                "pid": os.getpid(),
            },
            "capabilities": {
                "methods": sorted(self._methods),
                "jobKinds": list(SUPPORTED_JOB_KINDS),
                "maxConcurrentJobs": 1,
                "cooperativeCancel": True,
                "cancellationFallback": "terminate+restart",
                "progressEvents": True,
                "basicPitchAvailable": importlib.util.find_spec("basic_pitch") is not None,
            },
        }

    def _handle_ping(self, payload: Any) -> dict[str, Any]:
        echo = payload.get("echo") if isinstance(payload, dict) else None
        return {
            "echo": echo,
            "workerPid": os.getpid(),
            "uptimeMs": round((time.monotonic() - self._started) * 1000.0, 1),
        }

    def _handle_shutdown(self, payload: Any) -> dict[str, Any]:
        self._exit_after_response = True
        active = self._active_job()
        return {"ok": True, "activeJob": active.job_id if active else None}

    def _handle_job_start(self, payload: Any) -> dict[str, Any]:
        if not isinstance(payload, dict):
            raise protocol.ProtocolError(
                protocol.ERR_INVALID_PARAMS, "job.start payload must be an object"
            )
        kind = payload.get("jobKind")
        if not isinstance(kind, str) or not kind:
            raise protocol.ProtocolError(
                protocol.ERR_INVALID_PARAMS, "job.start requires a string 'jobKind'"
            )
        if kind not in SUPPORTED_JOB_KINDS:
            raise protocol.ProtocolError(
                protocol.ERR_UNKNOWN_JOB_KIND,
                f"unsupported jobKind {kind!r}",
                details={"supported": list(SUPPORTED_JOB_KINDS)},
            )
        active = self._active_job()
        if active is not None:
            raise protocol.ProtocolError(
                protocol.ERR_JOB_ALREADY_RUNNING,
                "a job is already running",
                details={"activeJobId": active.job_id, "maxConcurrentJobs": 1},
            )
        self._job_counter += 1
        job_id = f"job-{self._job_counter:04d}"
        if kind == JOB_KIND_TRANSCRIPTION:
            try:
                tparams = TranscriptionParams.from_payload(payload.get("params"))
            except ValueError as exc:
                raise protocol.ProtocolError(
                    protocol.ERR_INVALID_PARAMS, str(exc)
                ) from exc
            _warm_engine_imports()
            self._job = self._start_transcription_job(job_id, tparams)
        else:
            try:
                params = DemoLongTaskParams.from_payload(payload.get("params"))
            except ValueError as exc:
                raise protocol.ProtocolError(
                    protocol.ERR_INVALID_PARAMS, str(exc)
                ) from exc
            self._job = self._start_demo_job(job_id, params)
        return {"jobId": job_id, "jobKind": kind, "state": "accepted"}

    def _handle_job_cancel(self, payload: Any) -> dict[str, Any]:
        job_id = payload.get("jobId") if isinstance(payload, dict) else None
        if not isinstance(job_id, str) or not job_id:
            raise protocol.ProtocolError(
                protocol.ERR_INVALID_PARAMS, "job.cancel requires a string 'jobId'"
            )
        job = self._job
        if job is None or job.done.is_set() or job.job_id != job_id:
            raise protocol.ProtocolError(
                protocol.ERR_JOB_NOT_FOUND, f"no active job {job_id!r}"
            )
        job.cancel.set()
        return {"jobId": job.job_id, "cancellation": "requested"}

    def _handle_project_save(self, payload: Any) -> dict[str, Any]:
        """`project.save` — write a .hornscribe.json document (#100).

        Payload: ``{"path": str, "project": {...schema v1 dict...}}``.
        The document is validated through HornScribeProject.from_dict
        before anything touches disk; a missing sourceAudio.contentHash
        is computed here so the relink contract stays authoritative.
        Writes go through ProjectStore (atomic tmp+replace + recovery
        snapshot).
        """
        if not isinstance(payload, dict):
            raise protocol.ProtocolError(
                protocol.ERR_INVALID_PARAMS, "project.save payload must be an object"
            )
        path_raw = payload.get("path")
        if not isinstance(path_raw, str) or not path_raw.endswith(PROJECT_FILE_SUFFIX):
            raise protocol.ProtocolError(
                protocol.ERR_INVALID_PARAMS,
                f"project.save requires a path ending in {PROJECT_FILE_SUFFIX}",
            )
        project_data = payload.get("project")
        if not isinstance(project_data, dict):
            raise protocol.ProtocolError(
                protocol.ERR_INVALID_PARAMS, "project.save requires a 'project' object"
            )

        # Fill sourceAudio.contentHash when the caller only knows the
        # path — hashing is authoritative work the engine owns.
        source = project_data.get("sourceAudio")
        if isinstance(source, dict) and not source.get("contentHash"):
            original = source.get("originalPath")
            if isinstance(original, str) and original:
                source_path = Path(original)
                if source_path.is_file():
                    project_data = dict(project_data)
                    project_data["sourceAudio"] = {
                        "originalPath": original,
                        "contentHash": hash_file_sha256(source_path),
                    }

        try:
            project = HornScribeProject.from_dict(project_data)
        except ProjectError as exc:
            raise protocol.ProtocolError(
                protocol.ERR_INVALID_PARAMS, f"invalid project document: {exc}"
            ) from exc

        target = Path(path_raw)
        try:
            ProjectStore(target.parent).save(project, target)
        except OSError as exc:
            raise protocol.ProtocolError(
                protocol.ERR_JOB_FAILED, f"could not write project file: {exc}"
            ) from exc
        return {"path": str(target), "projectId": str(project.project_id)}

    def _handle_debug_hang(self, payload: Any) -> dict[str, Any]:
        seconds = 5.0
        if isinstance(payload, dict):
            raw = payload.get("seconds")
            if isinstance(raw, (int, float)) and not isinstance(raw, bool):
                seconds = float(raw)
        seconds = min(max(seconds, 0.0), 300.0)
        log.warning("debug.hang: wedging dispatch loop for %.1fs", seconds)
        time.sleep(seconds)
        return {"sleptSeconds": seconds}

    def _handle_debug_stacks(self, payload: Any) -> dict[str, Any]:
        """Return a text dump of all thread stacks (job debugging).

        Read-only; used to diagnose a job that appears stuck (e.g. an
        import deadlock in a daemon thread). Not a stable API.
        """
        import traceback

        frames = sys._current_frames()
        out: list[str] = []
        for tid, frame in frames.items():
            out.append(f"--- thread {tid} ---")
            out.extend(traceback.format_stack(frame))
        return {"threads": len(frames), "dump": "".join(out)}

    # ---- jobs ----------------------------------------------------------

    def _active_job(self) -> _Job | None:
        job = self._job
        if job is not None and not job.done.is_set():
            return job
        return None

    def _start_demo_job(self, job_id: str, params: DemoLongTaskParams) -> _Job:
        job = _Job(job_id=job_id, kind=JOB_KIND_DEMO_LONG_TASK, cancel=threading.Event())

        def emit(phase: str, **fields: Any) -> None:
            body: dict[str, Any] = {
                "jobId": job_id,
                "jobKind": JOB_KIND_DEMO_LONG_TASK,
                "phase": phase,
            }
            body.update(fields)
            self._emit_event("job.event", body)

        def run() -> None:
            try:
                run_demo_long_task(
                    job_id=job_id, params=params, emit=emit, cancel=job.cancel
                )
            except Exception:
                log.exception("job %s crashed", job_id)
                emit(
                    "failed",
                    error={
                        "code": protocol.ERR_INTERNAL,
                        "message": "job crashed unexpectedly",
                    },
                )
            finally:
                job.done.set()

        job.thread = threading.Thread(target=run, name=f"{job_id}", daemon=True)
        job.thread.start()
        return job

    def _start_transcription_job(
        self, job_id: str, params: TranscriptionParams
    ) -> _Job:
        job = _Job(
            job_id=job_id, kind=JOB_KIND_TRANSCRIPTION, cancel=threading.Event()
        )

        def emit(phase: str, **fields: Any) -> None:
            body: dict[str, Any] = {
                "jobId": job_id,
                "jobKind": JOB_KIND_TRANSCRIPTION,
                "phase": phase,
            }
            body.update(fields)
            self._emit_event("job.event", body)

        def run() -> None:
            try:
                run_transcription_job(
                    job_id=job_id, params=params, emit=emit, cancel=job.cancel
                )
            except Exception:
                log.exception("job %s crashed", job_id)
                emit(
                    "failed",
                    error={
                        "code": protocol.ERR_INTERNAL,
                        "message": "job crashed unexpectedly",
                    },
                )
            finally:
                job.done.set()

        job.thread = threading.Thread(target=run, name=f"{job_id}", daemon=True)
        job.thread.start()
        return job


def _warm_engine_imports() -> None:
    # Import the native engine stack on the main thread (ENG-002).
    # Loading numpy/onnxruntime DLLs for the first time from a non-main
    # thread can wedge inside create_module on Windows (loader-lock
    # interaction). Importing here — before the job thread starts —
    # makes the job thread hit sys.modules instead. Missing packages
    # are ignored: the job itself reports ENGINE_DEPENDENCY_MISSING
    # with the proper error code.
    # librosa is a lazy_loader package: importing the top level does NOT
    # pull the submodules the pipeline touches, so name them explicitly.
    for name in ("librosa.core.audio", "librosa.beat", "basic_pitch.inference"):
        try:
            importlib.import_module(name)
        except Exception:
            log.debug("engine warm-up import of %s failed", name, exc_info=True)
            break


def _reconfigure_stream(stream: TextIO, **kwargs: Any) -> None:
    """Best-effort ``TextIOWrapper.reconfigure`` (absent on odd streams)."""
    reconfigure = getattr(stream, "reconfigure", None)
    if callable(reconfigure):
        with contextlib.suppress(OSError, ValueError):
            reconfigure(**kwargs)


def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser(
        prog="hornscribe.worker",
        description="HornScribe engine sidecar (NDJSON over stdio; logs on stderr)",
    )
    parser.add_argument(
        "--version",
        action="version",
        version=(
            f"hornscribe-engine {hornscribe.__version__} "
            f"(protocol v{protocol.PROTOCOL_VERSION})"
        ),
    )
    parser.add_argument(
        "-v",
        "--verbose",
        action="store_true",
        help="debug-level diagnostics on stderr",
    )
    args = parser.parse_args(argv)
    logging.basicConfig(
        stream=sys.stderr,
        level=logging.DEBUG if args.verbose else logging.INFO,
        format="%(asctime)s %(levelname)s %(name)s: %(message)s",
    )
    # stdout is protocol-only: pin UTF-8 + '\n' so a Windows console
    # encoding or newline translation can never corrupt a frame.
    _reconfigure_stream(sys.stdout, encoding="utf-8", newline="\n", write_through=True)
    _reconfigure_stream(sys.stdin, encoding="utf-8")
    return Worker(sys.stdin, sys.stdout).serve()


if __name__ == "__main__":
    raise SystemExit(main())
